import{_ as l,V as o,W as c,Z as i,$ as d,a0 as t,Y as u,F as a,a1 as p}from"./framework-b1bd8911.js";const n={},s=u("<p>base-plugin 是 QuickMedia 各个插件的公共基础库，它不提供面向最终用户的某个具体功能，而是把 image-plugin、qrcode-plugin、markdown-plugin 等插件里都会用到的底层能力抽出来统一维护，比如文件读取、图片加载、gif 编解码、颜色处理、http 下载等工具类。</p><p>实际使用中，它通常会随着其他插件<strong>间接引入</strong>，一般不需要单独依赖；但如果你的项目里恰好也缺这么一套趁手的工具方法，直接拿来用也完全没问题（中央仓库坐标 <code>com.github.liuyueyi.media:base-plugin</code>）。</p><p>当前已支持的能力清单如：</p><ol><li><p>文件读写：<code>com.github.hui.quick.plugin.base.file</code></p><ul><li><code>FileReadUtil</code>：读取文件/流，兼容网络地址、绝对路径、<code>~</code> 用户目录、classpath 相对路径；魔数识别</li><li><code>FileWriteUtil</code>：保存流/文本到临时目录，递归建目录，文件信息解析</li><li><code>BasicFileUtil</code>：绝对路径判断、<code>~</code> 路径解析、按魔数识别文件类型</li></ul></li><li><p>IO 工具：<code>com.github.hui.quick.plugin.base.io.IoUtil</code></p><ul><li>流转可重复读的字节数组流、流转字符串</li></ul></li><li><p>图片加载与操作：<code>com.github.hui.quick.plugin.base.awt</code></p><ul><li><code>ImageLoadUtil</code>：按路径加载图片（含 ico）、加载 gif</li><li><code>ImageOperateUtil</code>：圆角图、圆形 logo、边框生成</li><li><code>GraphicUtil</code>：画布创建、高质量 Graphics2D 获取、缩放、png 转 jpg</li><li><code>ColorUtil</code>：int/html/字符串颜色与 <code>Color</code> 对象互转</li></ul></li><li><p>gif 编解码：<code>com.github.hui.quick.plugin.base.gif</code></p><ul><li><code>GifHelper</code>：gif 加载、多帧合成 gif 输出</li><li><code>GifDecoder</code> / <code>GifEncoder</code>：gif 的逐帧解析与逐帧编码</li></ul></li><li><p>http 工具：<code>com.github.hui.quick.plugin.base.http.HttpUtil</code></p><ul><li>从网络下载资源，返回输入流</li></ul></li><li><p>系统与进程：<code>com.github.hui.quick.plugin.base</code></p><ul><li><code>OSUtil</code>：windows 系统判断</li><li><code>ProcessUtil</code>：执行外部命令（ffmpeg 转码等场景在用）</li></ul></li><li><p>其他：<code>Base64Util</code>（图片与 base64 互转）、<code>DomUtil</code>（data-uri 拼接）、<code>NumUtil</code>（进制转换）</p></li></ol><p>各工具类的典型用法，请见速查手册：</p>",5);function g(r,h){const e=a("RouterLink");return o(),c("div",null,[s,i("ul",null,[i("li",null,[d(e,{to:"/git/quick-media/base/01.%E5%85%AC%E5%85%B1%E5%B7%A5%E5%85%B7%E7%B1%BB%E9%80%9F%E6%9F%A5.html"},{default:t(()=>[p("1.公共工具类速查")]),_:1})])])])}const f=l(n,[["render",g],["__file","index.html.vue"]]);export{f as default};
